"explanation": "全身を同系色または同一色でまとめたコーディネートはワントーンコーディネート（または同一色相コーディネート）と呼ばれ、すっきりとした統一感と洗練された印象を与える。\n\nA：全身をひとつの色でまとめるのはワントーン（または同一色）コーディネートであり、マルチカラーは多色使いの配色。\nC：コーディネート全体の70%以上を占める主役の色はベースカラーまたはドミナントカラーの説明。ポイントカラーは少量使いの差し色（アクセントカラー）に相当する。\nD：ベーシックカラーとは流行に左右されない定番色（白・黒・グレー・ネイビー・ベージュなど）のことであり、「季節ごとに変わる流行色」はトレンドカラーの説明。\n\n【頻出】ベースカラー・アソートカラー・アクセントカラーの役割と面積、およびベーシックカラーとトレンドカラーの区別は頻出。\n【混同注意】ワントーンコーディネート（同系色の統一）とモノクロコーディネート（白・黒・グレーのみ）は異なる概念。"
