"explanation": "色温度とは光の色を絶対温度（ケルビン：K）で表したものである。色温度が低い（約2000〜3000K）ほど赤みがかった温かみのある光色になり、色温度が高い（約6000K以上）ほど青白い冷たい光色になる。白熱電球は約2800K、昼光は約6500K。\n\nA：色温度と光色の関係が逆。高色温度が青白く、低色温度が赤みがかった暖色系の光。\nC：色温度は物理的な温度を℃で表すものではなく、ケルビン（K）で表す。白熱電球は約2800Kであり6500℃は誤り。\nD：太陽光の色温度は約5500〜6500K程度であり、1000〜2000Kは燃焼炎や電球以下の極めて低い色温度に相当し誤り。\n\n【頻出】色温度の単位（ケルビンK）と、低色温度＝暖色系・高色温度＝寒色系の関係は頻出。\n【混同注意】色温度の「高低」と「暖かい・冷たい」の関係は日常感覚と逆になるため混同しやすい。低K＝暖色（暖炉の炎）、高K＝寒色（青空）でイメージする。"
