"explanation": "演色性とは、ある光源のもとで物体の色がどれだけ忠実に（基準光源に近い状態で）再現されるかを示す性質であり、平均演色評価数（Ra）で表される。Ra100が最高で、自然光（太陽光）に最も近い。\n\nA：照度（ルクスlx）は光源の明るさの指標であり、演色性とは別の概念。\nC：演色性が「高い」光源ほど物体の色が自然光に近く見える。低い演色性では色の見え方が歪む。記述が逆で誤り。\nD：演色性と色温度は独立した概念であり、色温度が高くても演色性が低い場合がある。同義ではない。\n\n【頻出】RaとはRa100（基準）に近いほど演色性が高いという評価基準。美術館・食品・医療など色の正確な判断が必要な場所には高演色性光源が適するという応用知識も頻出。\n【混同注意】色温度（光の色み）と演色性（色の再現性）は全く別の概念。両方ともケルビンや数値で語られるが意味が異なる。"
