"explanation": "高圧ナトリウムランプは黄橙色の光が強く、演色性が低い光源である。道路照明や工場照明など、演色性よりも効率や視認性を重視する場所に使われる。美術館や食品売り場には高演色性の光源（高演色型蛍光灯・高演色LEDなど）が適しており、Dは誤り。\n\nA：正しい。白熱電球は約2800Kで赤みがかった暖かい光であり、Ra（演色評価数）はほぼ100で非常に高い。\nB：正しい。蛍光灯は白熱電球より高い色温度帯（3000〜6500K程度）があり、昼白色・昼光色等の製品がある。\nC：正しい。LEDは省エネ・長寿命であり、色温度や演色性は製品によって幅広い選択肢がある。\n\n【頻出】光源の種類（白熱・蛍光・LED・ナトリウム）と演色性の高低・用途の対応は頻出。\n【混同注意】「ナトリウムランプ＝高効率だが低演色性」という特徴を、LED等の高演色光源と混同しないよう注意。"
