"explanation": "中間混色とは、色が物理的に混ざるのではなく、小さな色点や回転により視覚的（生理的）に混色して見える現象の総称である。回転混色（コマに色を塗って回転させる）と並置混色（細かい色点を並べる＝モザイク・印象派絵画・カラー印刷の網点など）の2種類がある。明度は原色の中間値（平均値）になるのが特徴。\n\nA：明度が原色の平均値に近くなる点は正しいが、「加法と減法の中間的性質」という説明は曖昧で正確ではなく、正しい選択肢はCである。\nB：光の三原色と色料の三原色を同時に使うという説明は誤りであり、中間混色の定義でもない。\nD：補色のみを使うという制約はなく、常にグレーが生じるわけでもない。補色を回転混色すると中間グレーになる例はあるが、一般的定義ではない。\n\n【頻出】回転混色と並置混色の2種類と具体例（コマ・モザイク・印象派・カラーテレビ）は頻出。\n【混同注意】中間混色の明度は「平均値（中間）」であり、加法（上がる）でも減法（下がる）でもない点が特徴。"
