"explanation": "江戸時代の庶民は幕府による奢侈禁止令（派手な色の使用を制限）の影響を受け、茶色・鼠色系のくすんだ地味な色を工夫して多様化させた。「四十八茶百鼠（しじゅうはっちゃひゃくねず）」という言葉はそうした色彩文化の豊かさを表している。\n\nA：奢侈禁止令により原色・高彩度色は制限されており、「高彩度が広く流行した」は誤り。\nC：縹色（はなだいろ）は青系（青みがかった色）であり、赤系という説明は誤り。\nD：日本の伝統的な色彩感覚は中間色・くすみ色・淡い色が多く、高彩度・高コントラスト志向の西洋とは異なる傾向がある。\n\n【頻出】「四十八茶百鼠」と江戸時代の色彩文化（奢侈禁止令とくすみ色の多様化）は日本の色彩史の頻出トピック。\n【混同注意】江戸時代の「粋（いき）な色使い」はくすみ・渋みを特徴とし、現代的な「鮮やかで派手」なイメージとは正反対。"
