"answer": 3,
"explanation": "西洋において炎・情熱・戦争の象徴とされてきた色は赤であり、緑にそのような象徴的意味はない。緑は自然・生命・希望・再生などを象徴し、環境・健康・イスラム文化での神聖などと結びつく。\n\nA：正しい。黒は文脈によって死・喪（葬儀）から権威・エレガンス（高級ファッション）まで幅広い象徴性を持つ。\nB：正しい。古代の貝紫（ムレックス貝由来）は非常に高価で希少であり、ローマ皇帝・高位聖職者のみが使用できたことから紫が高貴の象徴となった。\nC：正しい。西洋では白は純潔・清浄・聖性の象徴であり、キリスト教文化圏の婚礼で白いウェディングドレスが定着している。\n\n【頻出】西洋における色の象徴（紫の貝紫由来・黒の多義性・白の純潔）は文化的背景とセットで頻出。\n【混同注意】「赤＝情熱・戦争・炎」「緑＝自然・生命・希望」という色の象徴の対応を確認する。"
