"answer": 1,
"explanation": "ベーシックカラーとは白・黒・グレー・ネイビー・ベージュ・ブラウンなど流行に関係なく常に使える定番色のことで、コーディネートの土台（ベース）として活用される。長期間使い続けられる汎用性の高さが特徴。\n\nA：季節ごとに変わる流行色はトレンドカラー（シーズンカラー）の説明であり、ベーシックカラーは流行に関係ない定番色。\nC：アクセントカラーは全体の5〜10%程度の少量使いで際立つ。50%以上では主役色となりアクセントとしての機能を失う。\nD：ベーシックカラーとアクセントカラーの組み合わせに補色関係という必須条件はない。さまざまな色相関係で成立する。\n\n【頻出】ベーシックカラー（定番・流行不問）とトレンドカラー（流行色）の区別、およびアクセントカラーの適切な面積（少量）は頻出。\n【混同注意】「ベーシック＝地味・無難」という印象から流行色と区別しにくいが、定義は「流行に左右されない汎用性」にある。"
