"explanation": "高彩度の赤は興奮・覚醒を高める効果があり、短時間の瞬発力向上には寄与することがあるが、長時間の集中・学習作業には逆効果（疲労・集中力低下）になる。集中力が必要な場所には低彩度・中明度のニュートラルな色や寒色系が適しているとされる。\n\nA：正しい。寒色系の落ち着いた色は不安・緊張を和らげる効果があるとされ、医療施設に有効。\nB：正しい。黄×黒のコントラストは自然界でも警戒色として機能し、工場・工事現場での安全色彩として標準的に使われる。\nC：正しい。暖色系は食欲増進・明るい雰囲気・活発なコミュニケーションを促す効果があり、飲食施設に適する。\n\n【頻出】用途別の適切な色彩選択（医療・工場・飲食・オフィス）は色彩計画の応用として頻出。\n【混同注意】「赤が注意を引く（誘目性）」と「赤が作業効率を高める（集中力）」は別の効果。赤は短時間の覚醒促進には有効だが、長時間作業には不向き。"
