"explanation": "分光反射率曲線とは、物体が各波長（例：380〜780nm）の光をどの割合（0〜100%）で反射するかをグラフ化したものである。この曲線の形状から物体の色を客観的に分析・比較することができ、メタメリズムの判定にも使われる。\n\nA：光源が発する光の波長ごとの強度を示すグラフは「分光分布（分光エネルギー分布）」であり、分光反射率曲線ではない。\nC：錐体細胞の波長感度を示す曲線は「等色関数」や「錐体の分光感度」と呼ばれ、分光反射率曲線ではない。\nD：混色時の明度変化を示すものは分光反射率曲線の定義ではなく誤り。\n\n【頻出】分光反射率曲線の定義（物体が反射する光の波長別割合）はメタメリズムの説明とあわせて頻出。\n【混同注意】「光源の分光分布」と「物体の分光反射率」は別のグラフ。どちらが光源についてのものか、物体についてのものかを区別して覚える。"
