"answer": 1,
"explanation": "手術室・精密作業場所では細部の視認が不可欠なため、JIS Z 9110では数千〜数万lxの高照度が推奨されている。一般事務は500〜1000lx、廊下・玄関は50〜200lx程度が目安。屋外直射日光は100,000lx以上に達することもある。\n\nA：一般オフィスの事務作業に必要な照度は500〜1000lx程度であり、10〜50lxでは暗すぎる。読書にも300lx以上が推奨される。\nC：住宅の玄関・廊下は比較的低照度（50〜200lx程度）で足り、手術室等の精密作業より低い。3000lx以上という記述は誤り。\nD：屋外直射日光下の照度は100,000lx（10万lx）以上に達することもあり、室内照明の500〜1000lxとは桁違いに高い。\n\n【頻出】用途別の目安照度（オフィス・住宅・精密作業）の大小関係と単位（lx）はJIS照明基準の応用として頻出。\n【混同注意】屋外直射日光の照度（10万lx超）と室内照明（数百〜数千lx）の桁の差を意識して覚える。"
