"explanation": "有彩色とは色相・明度・彩度の3属性すべてを持つ色のことをいう。一方、無彩色（白・灰色・黒）は色みがないため色相と彩度を持たず、明度のみを持つ。これが有彩色と無彩色の本質的な違いである。\n\nA：有彩色が3属性を持ち無彩色が明度のみを持つという関係が逆になっており誤り。\nC：無彩色は彩度のみを持つというのは誤り。無彩色は彩度がゼロであり、持つ属性は明度のみ。\nD：無彩色は色相と彩度を持たず、「彩度の値が異なるだけ」という記述は誤り。属性の有無そのものが異なる。\n\n【頻出】「有彩色＝3属性すべて保有」「無彩色＝明度のみ保有（色相・彩度はゼロ）」という対比は色彩の基礎として頻出。\n【混同注意】無彩色に「彩度がない（ゼロ）」と「彩度という属性を持たない」は同義。彩度がゼロであり、色相も意味を持たない点を理解する。"
