"explanation": "ハレーション現象とは、明度差がほとんどない（または同程度の）補色関係にある2色を隣接させたとき、境界部分がちらついて見えたり、まぶしく不安定な印象になる視覚的な現象をいう。高彩度の補色同士を接触させると特に生じやすい。\n\nB：明度差による境界の鮮明化は縁辺対比（マッハバンド）の説明に近く、ハレーションの定義ではない。\nC：同一トーンの色が同化して見える現象は色の同化現象の説明であり、ハレーションとは異なる。\nD：光の透過による残像はハレーションとは無関係であり、継時対比（陰性残像）などに関連する現象。\n\n【頻出】ハレーション現象の発生条件（高彩度補色同士・明度差が小さい）と視覚的な不安定さはグラフィック・ファッションの配色で注意事項として頻出。\n【混同注意】ハレーション（補色の明度差なし＝ちらつき）と補色対比（補色を並べて互いを引き立てる効果）は同じ補色の組み合わせでも目的・効果が異なる。"
