"explanation": "キリスト教（カトリック・プロテスタントの一部）の典礼色では、白は復活祭・聖誕祭など喜びの祭日に使われ純潔・喜びを象徴する。紫は待降節（アドベント）・四旬節（レント）に使われ、悔悛・準備・謙遜を象徴する。\n\nA：待降節・四旬節に使われるのは紫であり、赤ではない。赤は聖霊降臨日や殉教者の記念日に使われる。\nC：イスラム教では白は清潔・純粋の色として重視され、礼拝や巡礼（ハッジ）の白い衣装（イフラーム）など積極的に使用される。禁忌とする記述は誤り。\nD：仏教において黒が最も神聖とされ全ての仏具に義務付けられるという記述は誤り。金・赤・白など多様な色が使われ、宗派・地域によって異なる。\n\n【頻出】キリスト教の典礼色（白＝喜び・復活、紫＝悔悛・準備、赤＝聖霊・殉教）は宗教と色彩の文化的知識として頻出。\n【混同注意】紫の「悔悛・準備」のイメージは、欧米における紫の「高貴・王権」のイメージと並存している点に注意。文脈（典礼か文化か）で意味が異なる。"
