"answer": 1,
"explanation": "サイン計画における色彩設計では、情報の種類（案内・禁止・警告・誘導）や重要度に応じて色を使い分けることが基本である。また視認性（発見しやすさ）・誘目性（注目しやすさ）・可読性（読みやすさ）を考慮し、周囲の環境との対比も重要な検討要素となる。\n\nA：情報の重要度に応じた色の使い分けは安全で効果的なサイン計画の基本であり、全て同一色では区別がつかず情報伝達が機能しない。\nC：サインは周囲の環境（壁色・床色・照明）との対比によって視認性が変わるため、環境色との関係は重要な検討要素である。\nD：全てのサインに赤を義務付ける国際規格は存在しない。赤は禁止・危険の安全色彩として特定用途に使われる色。\n\n【頻出】サイン計画における色彩の役割（情報種別の色分け・視認性・誘目性・可読性の確保）は環境デザインの応用として頻出。\n【混同注意】安全色彩（JIS・ISO規格）はサイン計画の一部を構成するが、サイン全体の色彩計画は安全色彩の規定だけでは完結しない。"
