"answer": 0,
"explanation": "色立体（カラーソリッド）とは、色の三属性（色相・明度・彩度）を三次元空間に配置して色の体系全体を立体的に表現したモデルである。マンセルの色立体では中心軸が明度（縦軸）を表し、水平方向が彩度、周方向が色相を示す。\n\nB：色立体は3次元モデルであり、「平面で表示した2次元モデル」という記述は誤り。2次元で色相と彩度を表したものは色相環や色度図。\nC：色立体の中心軸は明度（縦軸：暗→明）を表す。「彩度が中心軸」という記述は誤り。彩度は中心軸からの距離（水平方向）で表される。\nD：色相によって到達できる最高彩度が異なるため、色立体は完全な球体にはならない（マンセルの色立体は非対称な形）。\n\n【頻出】色立体の構造（中心軸＝明度、水平距離＝彩度、周方向＝色相）はマンセル表色系の理解と合わせて頻出。\n【混同注意】色立体の中心軸が明度（縦）であり彩度（横）ではない点は、座標の読み違いが生じやすいため注意。"
