"answer": 1,
"explanation": "アナロガス（analogous）配色とは色相環上で隣接・近接する色相（通常30〜60度以内）を組み合わせた配色である。色相が近いため調和しやすく、統一感・自然な印象・穏やかな変化が特徴。自然界の色の組み合わせによく見られる。\n\nA：色相環の対極にある補色関係の配色はコンプリメンタリー（補色）配色の説明であり、アナロガスとは逆の特徴を持つ。\nC：全ての色相を均等に使う多色配色はポリクロマティック配色などに相当し、アナロガスの定義（近接色相）とは異なる。\nD：無彩色のみの配色はアクロマティック（achromatic）配色であり、モノクロマティック配色は同一色相内の配色（有彩色を含む場合もある）。アナロガスの定義ではない。\n\n【頻出】アナロガス（類似色相・近接・調和）とコンプリメンタリー（補色・対極・コントラスト）の対比は配色技法の最頻出比較問題。\n【混同注意】アナロガス＝「似た色同士」「穏やか・統一感」、コンプリメンタリー＝「反対の色」「強いコントラスト」と対比イメージで定着させる。"
