"explanation": "ジャッドの色彩調和の4原理のうち、秩序の原理とは色相・明度・彩度が規則的・系統的に配列された配色は調和するという原理である。なじみの原理（親近性の原理）とは、自然界や日常生活で見慣れた・親しまれた配色は調和して見えるという原理である。\n\nA：秩序の原理となじみの原理の内容が逆に記述されており誤り。秩序＝規則的配列、なじみ＝見慣れた配色。\nC：補色のみ・同一色相のみという限定はジャッドの原理にはなく、各原理の説明も誤り。\nD：秩序の原理・なじみの原理はジャッドの4原理であり、ムーン＆スペンサーの数学的調和論とは別の理論体系。\n\n【頻出】ジャッドの4原理（秩序・なじみ・共通性・明瞭性）の各名称と内容の対応は最頻出。4つ全ての定義を正確に覚える。\n【混同注意】秩序（規則的配列）となじみ（見慣れた配色）は名称からイメージが混同しやすい。「秩序＝ルールに従う配列」「なじみ＝慣れ親しんだ配色」と語源から定着させる。"
