"answer": 1,
"explanation": "タスク照明（task lighting）は机・カウンター・調理台など特定の作業面を局部的に高照度で照らす局部照明であり、アンビエント照明（ambient lighting）は空間全体に均一・柔らかな全般的な明るさを提供する全般照明である。2つを組み合わせることで効率的かつ快適な照明環境を実現できる。\n\nA：タスクとアンビエントは同義ではなく、局部照明（作業用）と全般照明（環境用）という異なる役割を持つ。\nC：特定の物体をスポットで照らす演出照明はアクセント照明（accent lighting）の説明であり、アンビエントとは異なる。\nD：タスク・アンビエント照明は住宅・オフィス・店舗など幅広い建築環境で適用される照明計画の基本概念であり、工場専用ではない。\n\n【頻出】タスク照明（局部・作業用）・アンビエント照明（全般・環境用）・アクセント照明（演出・スポット）の3種類の役割と違いは照明計画の頻出比較問題。\n【混同注意】3種類の照明（タスク・アンビエント・アクセント）はそれぞれ「作業効率」「空間の雰囲気」「強調・演出」という異なる目的を持つ。目的と種類をセットで覚える。"
