"explanation": "エクステリアの色彩計画では、自然光（太陽光）の角度・強度・色みが時間帯・季節・天候によって変化するため、朝・昼・夕方・曇天・晴天など様々な条件での色の見え方を確認することが重要である。また近隣景観との調和も考慮される。\n\nA：エクステリアの色彩は周囲の景観・隣接建物・自然環境との調和が重要な要素であり、「考慮不要」は誤り。景観法に基づく規制がある地域もある。\nC：屋外は太陽光・空の色・反射光など様々な光源の影響を受け、室内とは色の見え方が大きく異なる場合がある。「同じに見える」は誤り。\nD：高彩度の色が全地域で推奨・高評価という記述は誤り。景観条例では高彩度を制限している地域も多い。\n\n【頻出】エクステリア色彩計画における自然光の変化への配慮と景観調和の重要性は、景観色彩計画との関連で頻出。\n【混同注意】インテリアの色選定（室内光源での確認）とエクステリアの色選定（自然光・時間帯変化への対応）では確認すべき照明条件が異なる。"
