"explanation": "色のシンボリズムには、赤が注意・危険・熱を連想させるなど人類に普遍的な傾向も存在するが、白（日本・中国では喪、欧米では婚礼）や緑（イスラム文化での神聖）など文化・地域・時代によって象徴的意味が大きく異なる例も多い。グローバルな色彩計画では文化差への配慮が重要。\n\nA：色のシンボリズムが全人類に生得的・同一という主張は、文化人類学・色彩心理学の研究と矛盾する。白や緑の象徴性の文化差が典型的な反例。\nC：グローバル化によって色の意味が完全に統一・標準化されているわけではなく、文化的な差異は現在も存在する。\nD：色のシンボリズムは宗教・政治・マーケティング・日常生活の色使いに広く反映されており、「文学・芸術のみ」は誤り。\n\n【頻出】色の象徴性の普遍的傾向と文化差（白・緑・赤の文化による意味の違い）は色彩と文化の比較問題として頻出。\n【混同注意】「自然環境に由来する普遍的な色の反応（赤＝火・血・危険）」と「文化・宗教・歴史に由来する象徴（白＝喪 vs 純潔）」は形成の背景が異なる。"
