"explanation": "XYZ表色系（CIE1931表色系）はCIE（国際照明委員会）が規定した測色的な表色系で、あらゆる色をX・Y・Zの3つの三刺激値で客観的に表す。このうちYは輝度（明るさ）に相当し、色度はxy色度図上の座標で表される。\n\nB：XYZ表色系はマンセルではなくCIEが規定。X・Y・Zは色相・明度・彩度ではなく、等色実験に基づく三刺激値。\nC：無彩色はX・Y・Zが特定の比率（等エネルギー白色点付近）で等しい場合であり、いずれかがゼロで無彩色になるわけではない。3値が等しいと純色というのも誤り。\nD：XYZとRGBは数学的変換関係にあるが「直接置き換えられる同一体系」ではなく、変換行列を通じて関係づけられる異なる表色系。\n\n【頻出】XYZ表色系のCIEによる規定・Y値が輝度に相当するという特徴はカラーマネジメントの基礎として頻出。\n【混同注意】XYZ（測色的・客観的数値）とxy色度図（XYZから導かれる2次元座標）の関係を整理する。YがBrightness（明度）に対応する点は他の属性との混同に注意。"
