"answer": 0,
"explanation": "光束（lm：ルーメン）は光源から放射される光の総量、光度（cd：カンデラ）は光源の特定方向への光の強さ、照度（lx：ルクス）は被照射面に届く光の量、輝度（cd/m²）は光源や反射面の単位面積あたりの光の強さ（見た目の明るさ）を示す。\n\nB：各物理量の単位と意味が混在して誤って記述されており、照度の単位はlxであり cdではない。\nC：輝度の単位はlmではなくcd/m²。各物理量の単位が全て入れ替わっており誤り。\nD：光束・光度・照度・輝度はそれぞれ異なる単位（lm・cd・lx・cd/m²）を持ち、同一のlxで表されるわけではない。\n\n【頻出】4つの測光量（光束lm・光度cd・照度lx・輝度cd/m²）の定義と単位は照明の基礎として頻出。単位と意味のセットで覚える。\n【混同注意】照度（lx）と輝度（cd/m²）は混同されやすい。照度は「照らされる面の明るさ」、輝度は「発光・反射面の見た目の明るさ」という方向性の違いを意識する。"
