"answer": 1,
"explanation": "マンセルの色立体における同一明度面（等明度面）とは、縦軸（明度軸）の特定の高さを水平に切った断面であり、同一の明度値を持つすべての色相と彩度の組み合わせが配置された面である。この断面上では色相（周方向）と彩度（中心からの距離）が変化する。\n\nA：「同一彩度の水平断面で色相と明度が変化する」というのは等彩度面の誤った説明。同一明度面は明度が固定された水平断面。\nC：「同一色相を縦方向に並べた断面で明度と色相が変化する」というのは等色相面（縦断面）の説明であり、「色相が変化する」という部分が矛盾しており誤り。\nD：同一彩度と色相の両方が固定されると単一の色になるという記述は色立体上の1点の説明であり、「面」ではない。\n\n【頻出】色立体の断面の種類（等明度面・等色相面・等彩度面）と各断面で変化する属性の組み合わせは色立体の理解問題として頻出。\n【混同注意】「等明度面（水平断面：色相と彩度が変化）」「等色相面（縦断面：明度と彩度が変化）」「等彩度面（円筒断面：色相と明度が変化）」の3種類を整理する。"
