"explanation": "ヴィジリアン（Virgilian）配色とは、ローマの詩人ウェルギリウスの牧歌的・田園的世界観にちなんだ自然派の色彩概念で、植物・土・空・水など自然界の色から着想を得た、穏やかで調和のとれた自然色の配色を指す場合がある。エコロジカルカラーに通じる配色観。\n\nA：テトラード（90度4色）配色はヴィジリアン配色とは異なる技術的な配色分類であり別概念。\nC：無彩色のみの配色はアクロマティック配色であり、ヴィジリアン配色の定義とは関係がない。\nD：PCCSのビビッドトーンのみの高彩度配色はヴィジリアン配色とは全く関係なく、むしろ自然の穏やかな色みとは対照的。\n\n【頻出】自然・牧歌的世界観に由来する配色コンセプト（エコロジカル・ナチュラル・ヴィジリアン系）は色彩と文化の応用として出題される。\n【混同注意】ヴィジリアン配色は技術的配色分類（テトラード・トライアド等）とは異なり、テーマ・コンセプト由来の配色概念である点を理解する。"
