"explanation": "清潔感のイメージは、高明度・低彩度の明るく淡い色（白・アイボリー・ライトブルー・ペールグリーンなど）と最も強く結びつく傾向がある。医療・食品・衛生用品・歯科などの分野で白・水色系が多用される背景にはこのイメージが働いている。\n\nA：低明度・高彩度の暗く鮮やかな色は重厚・高級・ダイナミックなどのイメージと結びつきやすく、清潔感とは異なる。\nC：清潔感は特定の色相に限定されるものではなく、高明度・低彩度という属性条件が重要。紫系に限定されるという記述は誤り。\nD：暖色系のみが清潔感と結びつくという記述は誤り。清潔感には白・水色（寒色系）などが強く関連する代表色として挙げられる。\n\n【頻出】色のイメージと属性条件の対応（清潔感＝高明度・低彩度・白・水色系）はファッション・医療・食品の色彩計画で頻出。\n【混同注意】清潔感（高明度・淡い色）と爽やかさ（高明度・やや高彩度・青緑系）は近いイメージを持つが、彩度レベルが異なる場合がある。"
