"explanation": "インターナショナルカラーとは、グローバルなビジネス・ブランディング・パッケージデザインなどにおいて、特定の文化・地域に偏らず広く受け入れられやすい色彩の傾向や選択のことをいう。特に多国籍企業がグローバル展開する際の色彩計画で重要な概念。\n\nA：各国が規制する色という定義は存在しない。インターナショナルカラーは規制ではなく、グローバルに通用する色彩傾向の概念。\nC：国連の旗色（青と白）はインターナショナルカラーの一例になりうるが、その定義がこれに限定されるわけではない。\nD：インターカラーは流行色の予測機関であり、毎月発表する推奨色という説明も正確ではない。インターナショナルカラーとは別の概念。\n\n【頻出】グローバルな色彩計画（文化差を超えた色の選択）とインターカラー（流行色予測機関）は混同しやすい頻出テーマ。\n【混同注意】インターカラー（International Commission for Colour：流行色委員会）とインターナショナルカラー（国際的に受け入れられる色彩傾向）は名称が似ているが異なる概念。"
