"explanation": "高級感・ラグジュアリーのイメージは、黒（高貴・洗練・エレガンス）・深い紫（歴史的な王権・神秘）・ゴールド（富・輝き・栄光）・シルバー（モダン・技術的精密さ）などと強く結びつく傾向がある。これらは低明度または特殊な光沢感を持つ色として共通している。\n\nA：高明度・高彩度の鮮やかな色はポップ・活発・カジュアルなイメージと結びつきやすく、高級感のイメージとは対照的な場合が多い。\nC：原色のみが高級感と結びつくという記述は誤り。高級感には深みある中間色・無彩色・金属色が関連する。\nD：すべての文化で紫のみが高級感を担うという絶対的な記述は誤り。黒・金なども高級感の代表色として幅広く使われる。\n\n【頻出】高級感・ラグジュアリーと色の対応（黒・深い紫・金・銀）はファッション・ブランド・パッケージの色彩計画で頻出。\n【混同注意】「高彩度＝目立つ（誘目性）」と「低明度・深みある色＝高級感」は異なるイメージ方向性。高価格帯商品が原色ではなく深みある色を使う理由と結びつけて理解する。"
