"answer": 1,
"explanation": "OLED（有機EL）ディスプレイは有機発光素子が各画素で直接発光するため、バックライトが不要。バックライト非使用により完全な黒（発光ゼロ）が表現でき、コントラスト比が非常に高く、色域も広い。薄型・フレキシブルなどの特性も持つ。\n\nA：OLEDはバックライトを使わない自発光型ディスプレイであり、「バックライト必要・画素ごと制御不可」というのは液晶（LCD）の特性の一部であり、OLEDの説明として誤り。\nC：OLEDはRGB加法混色で発色するディスプレイであり、CMYKモードで発色するという記述は誤り。\nD：OLEDの輝度は製品によって様々であり、「屋外視認性が最も低い」という記述は一般的な事実とはいえない。\n\n【頻出】OLEDの特徴（自発光・バックライト不要・真の黒・高コントラスト・広色域）はディスプレイ技術の知識として頻出。\n【混同注意】液晶（LCD：バックライト使用・透過型）とOLED（自発光・バックライト不要）の発光方式の違いを明確に区別する。"
