"answer": 1,
"explanation": "萌黄（もえぎ）は春に萌え出る若葉のような黄みがかった明るい緑色を指す日本の伝統色名である。「萌ゆる黄（きみどり）」が語源とされ、若々しさ・生命力・春のイメージを持つ。\n\nA：「紅（くれない）」は鮮やかな赤系（紅花染めによる赤）の色であり、青みのある紫ではない。\nC：「藤色（ふじいろ）」は藤の花の色から名づけられた淡い青紫色であり、藤の花に由来する伝統色名。「藤の花と無関係」は誤り。\nD：「柿色（かきいろ）」は熟した柿の実のような黄みの橙色であり、青みがかった灰色という説明は誤り。\n\n【頻出】日本の伝統色名とその色相・由来の組み合わせは慣用色名の頻出問題。萌黄・藤色・柿色・紅などの代表的な伝統色名を色相と由来とともに覚える。\n【混同注意】色名の漢字から連想できる色（柿→橙色、藤→青紫、萌黄→黄緑）を視覚的なイメージと結びつけて記憶すると定着しやすい。"
