"answer": 1,
"explanation": "プロダクトデザインにおける色彩は多様な機能的役割を持つ。ボタン・スイッチの識別（どれを押すか）、危険部位・警告部分の視認性向上（安全色彩）、ブランドカラーによるアイデンティティ形成、さらにユーザーの感情・購買意欲への影響など、審美的・機能的・マーケティング的役割を同時に担う。\n\nA：プロダクトの色彩は装飾だけでなく機能・安全・使いやすさに直結する重要な設計要素であり、「装飾のみ」は誤り。\nC：製品の色彩を全て統一する国際義務規格は存在しない。安全色彩の規格（JIS・ISO）は特定の危険表示等に適用されるが、製品全体の色を規制するものではない。\nD：色彩はユーザーの感情・印象・購買意欲に大きな影響を与えることがマーケティング研究で示されており、「影響しない」は誤り。\n\n【頻出】プロダクトカラーの機能（識別・安全・ブランド・感情への影響）はカラーマーケティングとあわせて頻出。\n【混同注意】「安全色彩のJIS規格（危険表示等への適用）」と「製品全体の色彩計画（企業・デザイナーの判断）」は適用範囲が異なる。前者は義務的、後者は任意的。"
