"answer": 0,
"explanation": "反射率とは物体が入射光のうちどの割合を反射するかを示す値（0〜100%）で、白は反射率がほぼ100%（ほぼ全光反射）、黒は反射率がほぼ0%（ほぼ全光吸収）に相当する。反射率は主に明度と密接に関係する。\n\nB：白と黒の反射率が逆になっており誤り。黒は光を吸収する（反射率低い）、白は光を反射する（反射率高い）。\nC：反射率は色相だけでなく明度（明るさ）に大きく依存し、同じ色相でも明度が異なれば反射率は異なる。\nD：反射率による有彩色・無彩色の分類という概念は正確ではない。有彩色・無彩色の区別は色相・彩度の有無によって決まり、反射率の数値とは別の基準。\n\n【頻出】白（高反射率）・黒（低反射率）という反射率の基本と、明度との関係はマンセルの明度スケールとあわせて頻出。\n【混同注意】反射率（物理的指標：％）と明度（知覚的指標：マンセルV値など）は密接に関連するが、完全に同一ではない。反射率から明度を計算する変換式が存在する。"
