"answer": 1,
"explanation": "カラーユニバーサルデザイン（CUD）の基本的な実践方法として、色のみに頼った情報伝達を避け、形・文字・記号・模様・明度差（コントラスト）などを組み合わせることが推奨される。これにより色覚異常・高齢者・弱視者など多様な見え方をする人々が情報を正確に受け取れる。\n\nA：CUDは有彩色の使用を禁止するのではなく、有彩色を使いながらも「色だけに依存しない設計」を求める考え方であり、「全て白黒に置き換え義務」は誤り。\nC：CUDは先天性色覚異常者だけでなく、後天性色覚変化（加齢による）・弱視・低視力など幅広い人を対象とした包括的な設計思想。\nD：赤と緑の組み合わせは赤緑色覚異常者が区別しにくい典型的な組み合わせであり、CUDでは回避が推奨される。「積極的活用を定めている」は正反対で誤り。\n\n【頻出】CUDの実践原則「色のみに依存しない多重手段の活用」と、赤緑の組み合わせが問題になる理由は頻出実践問題。\n【混同注意】CUD（色のみに頼らない設計）とアクセシビリティ全般（物理的なバリアフリー含む）は概念の範囲が異なる。CUDは視覚的な情報設計に焦点を当てた概念。"
