"explanation": "暖色系（赤・橙など）は交感神経を刺激して心拍数・血圧の上昇、体感温度の上昇、活動・覚醒状態の促進などの生理的効果をもたらす傾向があるとされる。一方、寒色系（青・青緑など）は副交感神経を優位にしてリラックス・鎮静効果をもたらす傾向がある。\n\nA：リラックス・心拍数低下は暖色ではなく寒色系の効果とされる。暖色が副交感神経を優位にするという記述は誤り。\nC：寒色系は交感神経の刺激ではなく副交感神経の優位（鎮静・リラックス）と関連するとされており、「体温上昇・活動量増大」は暖色系の効果の説明であり誤り。\nD：暖色（活動・覚醒促進）と寒色（鎮静・リラックス）では生理的効果に異なる傾向があるとされており、「同一・差なし」は誤り。\n\n【頻出】暖色（交感神経刺激・覚醒・血圧上昇）と寒色（副交感神経優位・鎮静・リラックス）の生理的効果の対比は頻出。\n【混同注意】「暖色＝温かみ（心理的）」と「暖色＝交感神経刺激（生理的）」は別の作用だが連動している。心理的効果と生理的効果を混同しないよう整理する。"
