"explanation": "蛍光灯・LED照明の色温度区分として、電球色（約2700〜3000K：暖かみのある橙白色）が最も低く、温白色（約3500K：やや温かみのある白色）が中間、昼白色（約5000K：自然な白色）が高い区分となる。さらに高い昼光色（約6500K：青白い冷たい光）も存在する。\n\nA：電球色と昼白色の色温度が逆になっており誤り。電球色が低色温度（暖色光）、昼白色が高色温度（白色光）。\nC：3種類の色温度は異なり、同一の4000Kではない。3種類の呼称は色温度の違いを示すために設定されている。\nD：電球色が5000K・昼白色が3000Kというのは逆であり誤り。また温白色と電球色が同一というのも誤り。\n\n【頻出】電球色（低K・暖色）・温白色（中K）・昼白色（高K・白色）・昼光色（最高K・青白）の色温度の順列は照明選択の基礎として頻出。\n【混同注意】色温度の「高低」と「暖かい・冷たい」の関係は日常感覚と逆（低K＝暖色・高K＝寒色）。各光色の名称と色温度の数値をセットで整理する。"
