"answer": 0,
"explanation": "日本の交通信号機の「青（進め）」は、JIS安全色彩では「緑（安全・進行・誘導）」に相当する色が使用されているが、日本では慣習的に「青信号」と呼ばれている。信号機の実際の色は緑系であり、「青」と「緑」の文化的・言語的区分の歴史的背景を持つ。\n\nB：赤・黄・青はそれぞれ固有の意味（赤＝停止・禁止、黄＝注意・警告、青（緑）＝安全・進行）を持ち、互換性はない。\nC：黄色は「注意・警告（もうすぐ赤になる）」を意味し、「進め」の意味は持たない。\nD：交通信号機の「青」はJIS規格上の「緑」に相当し、CMYKのシアンとして規定されているわけではない。\n\n【頻出】日本の「青信号」が実際には緑色であることとJIS安全色彩の「緑＝安全・進行」の関係は色彩文化と安全色彩の融合テーマとして頻出。\n【混同注意】「青（Blue）」と「緑（Green）」の日本語における歴史的な区分の曖昧さ（青と緑が同一視された歴史）は日本の色彩文化の特徴的な事例として理解する。"
