"answer": 1,
"explanation": "病院・医療施設のサイン計画では、診療科・フロア・区域ごとに色分けした誘導システム（カラーコーディング）が有効である。色を手がかりに「青のゾーンが内科」「緑のゾーンが小児科」のように患者・来訪者が直感的に目的地を識別できる設計が、迷いや不安の軽減に役立つ。\n\nA：全サインを赤で統一すると赤の安全色彩的意味（禁止・危険）と混同され、患者に不安・混乱を与える可能性がある。緊急を常に意識させる設計は不適切。\nC：色と文字を組み合わせることが最も効果的であり、「色を使わない方がよい」という記述は誤り。色は迅速な場所識別に不可欠な要素。\nD：無彩色のみで構成することを義務付ける規格は存在しない。識別性・誘目性を高めるために有彩色が積極的に使われる。\n\n【頻出】医療施設でのカラーコーディング（区域別色分け誘導システム）はサイン計画と色彩機能の応用として頻出。\n【混同注意】「病院は落ち着いた色でなければならない」という印象から「サインも目立つ色は不適切」と誤解しやすいが、サインの視認性・識別性は安全に直結するため色彩の活用が重要。"
