"explanation": "日本では慶事（結婚・出産・お祝いなど）に紅白（赤と白）の配色が用いられ、弔事（葬儀・お悔やみなど）には白・黒・薄墨（グレー）などの配色が使われる文化がある。水引の色も慶事は紅白・金銀、弔事は白黒・黄白などで明確に区別される。\n\nA：赤・白の包装は慶事で使われる代表的な組み合わせであり、「弔事専用」という記述は逆で誤り。\nC：慶事と弔事で色による区別を明確に行うのが日本の包装文化の特徴であり、「区別が行われない」は誤り。\nD：紅白は慶事の代表的な配色として現代でも広く使われており、「避けられる傾向」という記述は誤り。\n\n【頻出】日本の慶事・弔事の色彩区別（慶事：紅白・金銀、弔事：白黒・薄墨）は日本の色彩文化として頻出。\n【混同注意】日本の慶事の代表色「紅白（赤と白）」を、白が喪の象徴であるという知識と混同しないよう注意。慶事では赤（紅）と白のセットが吉祥色として機能する。"
