"answer": 0,
"explanation": "ベツォルト＝ブリュッケ現象とは、同一の色でも光の強度（輝度）が変化すると知覚される色相が変化して見える現象である。明るくすると黄・青みが増し、暗くすると赤・緑みが増す傾向がある。輝度と色相知覚の関係を示す視覚現象。\n\nB：境界付近の明度差強調は縁辺対比（マッハバンド）であり、ベツォルト＝ブリュッケ現象とは異なる。\nC：プルキンエ現象（明暗移行時に青系が明るく見える）とは異なる現象。プルキンエは錐体・桿体の切り替えによる現象、ベツォルト＝ブリュッケは輝度変化による色相知覚の変化。\nD：並置混色（色点が混合して見える）はベツォルト＝ブリュッケ現象とは全く別の概念。\n\n【頻出】ベツォルト＝ブリュッケ現象（輝度変化→色相知覚の変化）はプルキンエ現象・縁辺対比と区別して覚える視覚現象の頻出問題。\n【混同注意】プルキンエ（明暗移行・錐体↔桿体）とベツォルト＝ブリュッケ（輝度変化・色相知覚変化）は「明るさ変化に関する現象」として混同されやすい。発生の仕組みと結果が異なる。"
