"answer": 1,
"explanation": "コンセプトボード（ムードボード）とは、色彩計画・インテリア・ファッション・グラフィックなどのデザインプロジェクトにおいて、方向性・雰囲気・世界観・イメージを視覚的に共有するため、写真・色見本・素材サンプル・テクスチャー・キーワードなどを組み合わせたビジュアルツールである。\n\nA：コンセプトボードは事後のポートフォリオではなく、プロジェクト前半のコンセプト共有・提案段階で作成・使用するツール。\nC：RGB・CMYK数値を記録したチャートはカラーパレットやカラーガイドラインと呼ばれるものであり、コンセプトボードの定義ではない。\nD：コンセプトボードはデザイナーがコンセプトを視覚化・提案するための創造的なツールであり、「デザイナーの提案要素を含まない」という記述は誤り。\n\n【頻出】コンセプトボード・ムードボードの目的（ビジョン・雰囲気の視覚的共有）と使用タイミング（計画前半・提案段階）はデザインプロセスとして頻出。\n【混同注意】コンセプトボード（方向性のビジュアル化）とカラースキーム（具体的な色の決定）はデザインプロセスの異なるステップ。前者が先行し、後者がより具体化した段階で作成される。"
