"answer": 0,
"explanation": "白・明るい色（高明度色）は太陽光を多く反射し（高反射率）、建物内部に熱を取り込みにくくする。そのため夏の冷房負荷の軽減に効果があるとされる。逆に黒・暗い色（低明度色）は太陽光を吸収しやすく（高吸収率）、建物が蓄熱しやすくなる。\n\nB：黒・暗い色は太陽光を「吸収」しやすく、「反射」は少ない。夏の冷房負荷を「増やす」方向に働くため、記述が逆で誤り。\nC：外壁色は建物の熱吸収・反射率に影響し、室内温度・エネルギー消費に影響することが実証されている。「影響なし」は誤り。\nD：白は太陽光を「反射」する（吸収しにくい）ため、冬の暖房効率を上げる効果はむしろ期待しにくい。暖房効率向上には暗い色の方が蓄熱効果がある。\n\n【頻出】外壁色の反射率と夏の冷房負荷・ヒートアイランド対策との関係はサステナブルデザインの応用として頻出。\n【混同注意】「白＝高反射率＝夏に有効（冷房負荷軽減）」と「黒＝高吸収率＝冬に有効（蓄熱効果）」という季節と色の方向性の使い分けを整理する。"
