"explanation": "オレンジは活力・陽気・温かみ・元気・収穫・秋などのポジティブなイメージを持つ。仏教の僧の袈裟の色（特に東南アジア）、ハロウィンのカラー（秋・収穫・祝祭）、交通安全色（視認性の高い警戒色）、ファストフードのブランドカラーなど多様な文脈で使われる。\n\nA：オレンジが危険・毒の象徴として食品使用が避けられるという事実はなく、むしろ食欲増進・エネルギーイメージで食品分野に広く活用される。\nC：純潔・清浄の象徴は白であり、オレンジはそのような宗教的文脈での使われ方が主ではない。\nD：日本でオレンジが禁忌色とされている事実はない。柿色・橙色など日本の伝統色にもオレンジ系は存在する。\n\n【頻出】オレンジのイメージ（活力・陽気・食欲・収穫）と多様な使用場面（仏教・ハロウィン・安全色）は色彩文化の応用として頻出。\n【混同注意】オレンジの安全色彩的な使用（工事現場の高視認性）と、食品・飲食業での食欲増進効果という異なる文脈での機能を区別して覚える。"
