"explanation": "イメージスケールにおいて、ダイナミック（dynamic）は高彩度・強いコントラスト・暖色系の活動的・力強い配色と結びつき、エレガント（elegant）は低彩度・上品なトーン・落ち着いた色と結びつく傾向がある。両者はイメージスケール上の異なる方向（概ね対角に近い位置）に配置される。\n\nA：ダイナミックとエレガントは同一位置ではなく、イメージスケール上で異なる方向性の対照的な位置関係にある。\nC：ダイナミックが低明度・低彩度の暗くくすんだ色と結びつくという記述は逆。ダイナミックは高彩度・強いコントラストが特徴。\nD：ダイナミックは暖色系との関連が強く、「寒色系のみ」という限定は誤り。またエレガントも暖色・寒色両方の色を含み得る。\n\n【頻出】イメージスケール上のポジション（ダイナミック×エレガント・ウォーム×クールなど）と配色特性の対応は感性評価の応用として頻出。\n【混同注意】「ダイナミック＝動的・強い・高彩度」と「エレガント＝静的・洗練・低彩度」という対比軸を、イメージスケールの2軸構造と結びつけて理解する。"
