"explanation": "対比調和とは、色相・明度・彩度の差が大きい色同士でも秩序感や意図があれば美しい調和が成立することを示す概念。類似調和とは共通する属性（色相・トーンなど）がある配色が調和しやすいという概念。両者は調和の成立する異なるメカニズムを示す対概念。\n\nB：対比調和と類似調和は異なるメカニズムの調和の形であり、「区別する意味がない」は誤り。デザイン目的に応じてどちらを意図的に用いるか判断することが重要。\nC：混色は物理的な色の操作であり、対比調和の定義ではない。また類似調和の定義も「同じ色の繰り返し」ではなく「共通属性による調和」。\nD：対比調和と類似調和のどちらが優れているとは一概にいえず、目的・文脈・デザインの意図によって使い分けられる。「常に対比調和を優先」という絶対的な優位性は誤り。\n\n【頻出】対比調和（差による調和）と類似調和（共通性による調和）の対概念はジャッドの原理（明瞭性・共通性）と対応する形で頻出。\n【混同注意】「類似は地味・対比は派手」という印象から、対比調和が「美しい」類似調和が「美しくない」と誤解しやすい。どちらも「調和」であることを確認する。"
