"explanation": "ヤング＝ヘルムホルツの三色説（Young-Helmholtz theory）は、人間の網膜には赤（L型）・緑（M型）・青（S型）の3種類の錐体細胞があり、これらが受け取る刺激量の組み合わせによってあらゆる色を知覚するという理論である。現代の色覚研究の基礎となっている。\n\nB：「黄・青・赤の3種類の受容体が拮抗作用」という説明は反対色説（ヘリング説）の内容に近く、三色説の記述としては誤り。\nC：三色説の3色はCMY（印刷の三原色）ではなくRGB（光の三原色）に対応した錐体細胞。CMYで色知覚を説明するというのは誤り。\nD：三色説は照明理論ではなく色覚の生理学的・心理物理学的理論。「3種類の光源が必要」というのは誤り。\n\n【頻出】三色説（ヤング＝ヘルムホルツ：赤・緑・青の3種類の錐体細胞による色覚）は色覚の生理的基礎として頻出。\n【混同注意】三色説（3種類の錐体細胞の組み合わせ）と反対色説（ヘリング：赤-緑・青-黄・白-黒の拮抗する3対の視細胞）は異なる色覚理論。現代では両説を統合した段階説が有力。"
