"explanation": "グライド調和（glide harmony）とは、色相・明度・彩度のいずれかの属性が一方向に滑らかに（グライドするように）変化していく配色に生まれる調和のことをいう。グラデーション配色の調和原理と密接に関連し、段階的な変化がリズム感と統一感をもたらす。\n\nB：同一トーンに揃えた配色の調和はドミナントトーン配色・トーンイントーン配色の原理であり、グライド調和とは異なる。\nC：補色2色のみで構成された配色の調和はコンプリメンタリー調和（補色調和）であり、グライド調和の定義ではない。\nD：グレースケールの段階的配置に生まれる調和はグライド調和の一例になりうるが、グライド調和はグレースケールに限定されるものではなく、有彩色の属性変化にも適用される。\n\n【頻出】グライド調和（属性の段階的変化による調和）はグラデーション配色の理論的背景として頻出。オストワルトの系列調和とも関連する。\n【混同注意】グライド調和（変化の連続性・方向性）とリピテーション調和（繰り返しによる調和）はどちらも「秩序」に基づく調和だが、変化するか反復するかという方向性が異なる。"
