"explanation": "カーテン・ブラインドには色付きのものを使用すると、透過する自然光の色が着色されて室内に差し込み、空間全体の色雰囲気（アンビエントカラー）に影響を与える。例えば黄色のカーテン越しに光が差し込むと室内が温かみのある黄色がかった光で満たされる効果がある。\n\nA：カーテンを壁と同色にする規定は存在せず、アクセントカラーとして壁と異なる色を使う手法も広く行われる。\nC：ブラインドの色は日射吸収・反射に関わり、暗い色は熱を吸収しやすく室内の体感温度にも影響を与える。「色は体感温度に影響しない」は誤り。\nD：カーテンを常に壁より高彩度にすることが奥行きをもたらすという規則はなく、目的・空間の大きさ・他の要素との調和によって適切な選択が異なる。\n\n【頻出】カーテン・ブラインドの色が透過光・室内雰囲気・体感温度に与える影響はインテリア色彩計画の実践知識として頻出。\n【混同注意】「カーテンの色が透過光を着色する効果（光の色への影響）」と「カーテンの反射色が室内の雰囲気に影響する効果（反射光への影響）」は異なるメカニズムだが、どちらも室内の色環境に影響する。"
