"explanation": "等価値系列（isotone series）はオストワルト表色系の概念で、W（白量）・K（黒量）・C（純色量）の3要素のうちいずれか一つが等しい色の系列を指す。純色量が等しい系列・白量が等しい系列・黒量が等しい系列のそれぞれの同系列上にある色は調和するという等価値調和（isotone harmony）の理論の基礎となっている。\n\nB：マンセルの等明度面（同一V値の色）は存在するが、「等価値系列」という用語はオストワルト体系の概念であり、マンセルの用語としては通常用いられない。\nC：PCCSのトーンは明度×彩度の組み合わせによるグループであり、オストワルトの等価値系列とは異なる概念。\nD：CIEのXYZ値の等値系列は測色的な概念だが、「等価値系列」という調和理論の用語としてはオストワルトの体系で用いられる。\n\n【頻出】オストワルトの等価値系列（W・K・Cの一つが等しい系列の調和）はオストワルト色彩調和論の核心概念として頻出。\n【混同注意】オストワルトの等価値系列（W・K・Cの一値が等しい）とビレンの系列調和（同じ混合比率系列の調和）は異なる人物の異なる理論。どちらも系列的調和の考え方だが、基準とする値が異なる。"
