"explanation": "ショールームや展示スペースでは、展示品（製品・アート・素材サンプルなど）の色が正確に・魅力的に見えるよう、背景色は低彩度の中性的な色（白・グレー・ニュートラルベージュなど）を基本とする。背景が高彩度だと色の対比・同化が生じて展示品の色が歪んで見えるリスクがある。\n\nA：展示品と同系色・高彩度の背景は色の同化効果で展示品が背景に埋もれたり、強い対比で色が歪んで見える恐れがある。「まとまりを強調」のためだけでなく正確な色判断を妨げる。\nC：ショールームでは展示品の色を忠実に見せるために演色性の高い照明（Ra90以上）の使用が重要であり、「演色性は考慮不要」は誤り。\nD：高彩度の黒い背景は全ての展示品の色が正確に見えるという業界標準はなく、黒背景は特定の展示演出（宝石・発光製品など）に限定的に使われる手法。\n\n【頻出】ショールーム・展示スペースの背景色の基本（低彩度・中性的・展示品を引き立てる）と高演色性照明の重要性はセットで頻出。\n【混同注意】美術館・博物館（アート展示・文化財保護）とショールーム（製品の色を正確に見せる商業空間）の照明・色彩計画は共通する部分もあるが目的が異なる場合がある。"
