"explanation": "波長の物理的変化と色相の知覚的変化は均等（等間隔）ではない。スペクトルの中央付近（緑色域）では同じ波長変化でも色相の知覚変化が小さく（鈍感）、端部（赤・紫付近）では変化が大きい（敏感）という不均一な対応関係がある。「波長変化1nmごとに均等に色相が変化する」というDの記述は誤り。\n\nA：正しい。色相は有彩色のみが持つ属性であり、白・黒・グレーなどの無彩色は色相を持たない。\nB：正しい。色相環の構造として、隣接色相（類似色相）は差が小さく、反対側（補色）は差が最大となる。\nC：正しい（概ね）。白・黒・灰色を混ぜると明度（白・黒で変化）・彩度（全て低下）が変化するが、色相は基本的に変化しない。ただし大量に混ぜると知覚的にわずかな色相シフトが生じる場合もある。\n\n【頻出】波長と色相知覚の非均等な対応関係はスペクトルの均等性に関する誤解を問う頻出ポイント。知覚的等間隔性との関連で出題される。\n【混同注意】物理的な波長（電磁波の測定値）と知覚的な色相（人間が感じる色みの違い）は同じ変化量でも対応が異なる点が重要。測色学と色彩心理学の接点の問題。"
