"answer": 0,
"explanation": "UGR（Unified Glare Rating：統一グレア指標）は室内照明における不快グレアの程度を数値化した国際的な指標（CIE規格）であり、値が小さい（低い）ほどグレアが少なく快適な視環境であることを示す。オフィス・学校・病院などの照明設計でUGR≦19などの基準が設けられる。\n\nB：演色性を示す指標は平均演色評価数Ra（またはCRI）であり、UGRではない。UGRは不快グレアの指標。\nC：照度の均一性は照度均一度（均斉度）として別途管理される指標であり、UGRとは異なる。\nD：色温度はケルビン（K）で表され、UGRとは全く別の指標。電球色・温白色・昼白色の区別にUGRは使用されない。\n\n【頻出】UGR（不快グレアの数値指標・値小＝快適）はRa（演色性）・照度（lx）・色温度（K）などの照明評価指標の区別を問う比較問題として頻出。\n【混同注意】照明の評価指標（照度lx・演色性Ra・色温度K・グレアUGR・輝度cd/m²）はそれぞれ異なる評価対象を持ち、数値の方向性（大きい方がよいか小さい方がよいか）も異なる。"
