"explanation": "コンプリメンタリー配色（補色配色）を効果的に使うための実践的な調整として、①面積比に変化をつける（一方を大面積・他方を小面積）、②一方または両方のトーンを下げる（彩度を低くしてハレーションを防ぐ）、③セパレーションカラー（白・黒など）を挿入して対比を和らげるなどの手法が有効。\n\nA：2色の明度差をゼロにすると（同明度の高彩度補色同士）ハレーション現象が生じやすく、視覚的に不安定になる。最も重要な条件とは逆効果になる場合がある。\nC：高彩度同士の等面積補色配色はハレーションを起こしやすく、全ての場面で最も美しいとはいえない。面積比の調整や彩度の調整が必要。\nD：補色配色（コンプリメンタリー）は2色の補色関係で成立するものであり、「3色以上でなければ成立しない」は誤り。3色以上の補色的関係はトライアドやスプリットコンプリメンタリーに相当する。\n\n【頻出】補色配色の有効な調整方法（面積比の変化・トーンダウン・セパレーション挿入）はハレーション現象の対処法とあわせて頻出実践問題。\n【混同注意】補色を使うこと自体（コンプリメンタリー配色）と補色を効果的に使うための条件（調整方法）は別の問題。「補色＝必ず美しい」ではなく、調整があって初めて効果的な配色になる。"
