"explanation": "マゼンタは1856年にウィリアム・パーキンが18歳のときにコールタールからモーヴ（最初のアニリン染料）を偶然合成したことに始まる化学染料革命の流れの中で生まれた。化学染料の登場以前は高価な天然染料しかなかったが、安価な化学染料の普及によって庶民も多彩な色の衣服を着られるようになった（色の民主化）。マゼンタの名はイタリアのマジェンタの戦い（1859年）に由来する。\n\nB：貝から抽出される染料は貝紫（ムレックス貝由来）であり、マゼンタの説明ではない。マゼンタはアニリン染料（石炭タール由来の化学染料）。\nC：マゼンタは19世紀に発見・命名された色名であり、「20世紀のデジタル印刷技術で初めて作られた」は誤り。CMYKの基本色としてのマゼンタはそれ以前から存在する。\nD：マゼンタの名前はイタリアのマジェンタ（Magenta）という都市名に由来するのは正しいが、「特産の赤い花から抽出した天然染料」という説明は誤り。化学染料の命名にその地での戦いが使われた。\n\n【頻出】パーキンのアニリン染料発見（1856年）と化学染料による色の民主化は色彩史の重要な転換点として頻出。\n【混同注意】マゼンタ（化学合成染料）と貝紫（天然染料）は全く異なる起源を持つ。「染料の歴史で重要な赤紫系の色」という共通点から混同されやすい。"
