"explanation": "江戸時代には幕府の奢侈禁止令（倹約令）により、庶民が紫・紅・緋などの華やかな色の衣服を着ることが制限された。しかし庶民は制限の中で茶・鼠・藍などの色に微妙なバリエーション（四十八茶百鼠）を生み出し、粋（いき）という美意識のもと制約を逆手に取った独自の色彩文化を発展させた。\n\nB：奢侈禁止令は主に庶民（町人・農民）を対象とした制限であり、「武士のみ」という記述は誤り。武士にも身分に応じた色規定があった。\nC：白・黒のみが庶民に許されたという記述は誤り。藍・茶・鼠など複数の色系統が使用可能で、その範囲内で多様な色の工夫が行われた。\nD：禁色は日本固有の宮廷・幕府制度に由来するものであり、「世界的な国際条約」は誤り。\n\n【頻出】江戸時代の奢侈禁止令→四十八茶百鼠という色彩文化の発展は日本色彩史の核心テーマとして頻出。「粋」の美意識との関連も重要。\n【混同注意】禁色（禁じられた色）と御免色（特別に許可された色）は正反対の概念。高貴な人物が高価な染料の色を独占するという日本の伝統的な色彩秩序を理解する。"
