"explanation": "ステンドグラスはゴシック建築の大聖堂（シャルトル大聖堂・パリのサント・シャペルなど）において、厚い石壁に大きな窓を設けることで実現された芸術技法。色付きガラスを通じた色光が聖書の物語を語り、神の光として信者の精神的体験を高める宗教的・美的役割を果たした。\n\nB：ステンドグラスの技術は中世（12〜13世紀頃）に発展したものであり、「19世紀に発明」は誤り。\nC：ステンドグラスは透過色（光源色）による発色であり、ガラスを重ねると光が減衰して暗くなる（減法に近い性質）。「重ねるほど明るく鮮やか」という記述は誤り。\nD：ステンドグラスは西欧（ヨーロッパ）で発展した技法であり、日本の寺院建築に由来するという記述は歴史的事実と全く異なり誤り。\n\n【頻出】ステンドグラスの宗教的・美的機能（神の光・ゴシック建築との関係）と透過色の原理は色彩史・光と色の基礎知識として頻出。\n【混同注意】ステンドグラス（透過色・光を透過させて発色）と壁画・フレスコ（反射色・顔料の反射で発色）は色の成立原理が異なる。"
