"explanation": "ポップアート（Pop Art）は1950〜60年代にイギリス・アメリカで起こった芸術運動で、アンディ・ウォーホル・ロイ・リキテンスタインらが大量消費社会・広告・テレビ・漫画などの大衆文化を素材として使い、高彩度・原色的・鮮やかな色使いで消費社会の視覚文化を表現した。\n\nB：ポップアートはバウハウスの合理主義・無彩色基調とは対照的に、カラフルで商業的な色彩を積極的に使った運動。「白・グレー基調」は誤り。\nC：ポップアートは20世紀（1950〜60年代）に起こった運動であり、フランス革命期（18世紀末）とは全く異なる時代。\nD：ポップアートは鮮やかな色彩表現を特徴とする視覚的な芸術運動であり、「色彩を一切使用しない」は誤り。\n\n【頻出】ポップアートの色彩特徴（高彩度・原色・大衆文化の色を使用）とアンディ・ウォーホルの作品（マリリン・モンロー・キャンベルスープ缶など）は色彩史・文化として頻出。\n【混同注意】ポップアート（カラフル・大衆文化）とミニマリズム（シンプル・無彩色・素材の質感）は20世紀の対照的な美術運動として比較問題に出やすい。"
