"answer": 0,
"explanation": "アール・ヌーヴォー（Art Nouveau）は19世紀末〜20世紀初頭（1890〜1910年代頃）にヨーロッパで流行した装飾美術運動で、自然・植物・昆虫・女性をテーマにした有機的な曲線フォルムとともに、緑・金・薄紫・乳白色・淡い青など自然界に由来する柔らかい色調が特徴的。ミュシャ・ガレ・ギマールらが代表的な作家。\n\nB：直線・幾何学形・赤青黄原色＋黒の組み合わせはオランダのデ・スティール（モンドリアンなど）の特徴であり、アール・ヌーヴォーとは逆の美学。\nC：アール・ヌーヴォーは日本の浮世絵（ジャポニスム）から曲線・フラットな色面・輪郭線などの影響を受けた側面はあるが、浮世絵の色使いを「そのまま移植した」という記述は誤り。\nD：工業的素材とグレー・シルバーの色調はアール・デコや近代建築に関連する要素であり、アール・ヌーヴォーの特徴ではない。\n\n【頻出】アール・ヌーヴォーの色彩特徴（有機的フォルム・自然由来の柔らかい色調）はアール・デコとの比較で頻出。\n【混同注意】アール・ヌーヴォー（有機的・曲線・自然色調）とアール・デコ（幾何学的・直線・金属的色調）は1900年代前後と1920〜30年代の連続する異なる装飾様式。"
