"explanation": "弱視者（低視力・コントラスト感度が低い状態）向けの色彩設計では、文字・サイン・重要情報と背景の間に十分な明度差（コントラスト比）を確保することが最も重要な基本原則。WCAGでは通常テキストにコントラスト比4.5:1以上、大きいテキストに3:1以上などの基準が設けられている。\n\nB：細かい模様やテクスチャーは弱視者にとって判別が困難になりやすく、「多用して情報量を増やす」は逆効果になる場合がある。シンプルで明快なコントラストの確保が重要。\nC：色相の多様性より明度差の確保の方が弱視者の視認性に大きく影響する。「明度差より色相多様性が優先」は誤り。\nD：弱視者（残存視力を持つ）と全盲者（視力がない）は異なるニーズを持ち、同一の設計アプローチは適切でない。弱視者には視覚的なコントラスト確保が有効。\n\n【頻出】弱視者向けのコントラスト比の重要性（明度差確保）とWCAGのアクセシビリティ基準は視覚アクセシビリティの頻出テーマ。\n【混同注意】弱視（low vision：残存視力あり）と全盲（blindness：視力なし）は全く異なる視覚状態。それぞれに適した設計アプローチが異なる点を区別する。"
