"explanation": "染色堅牢度（color fastness）とは繊維製品の染色が、光・洗濯・摩擦・汗・乾燥クリーニングなどの外的条件に対してどの程度色を保持するか（変退色・汚染しにくさ）を示す指標である。JIS・ISO規格によってグレースケールで1〜5級（5が最良）で評価される。\n\nB：光照射で色が増加（鮮やかになる）という現象を測定するというのは誤り。染色堅牢度は色の「保持性・退色しにくさ」を評価する指標。\nC：染色堅牢度は洗濯堅牢度・耐光堅牢度・摩擦堅牢度・汗堅牢度など複数の項目が含まれる総称的な指標であり、「洗濯のみ」という記述は誤り。\nD：堅牢度が低い場合は一般的に退色（色が薄くなる・変色する）が生じる。「濃くなる傾向」という記述は一般的でなく誤り。\n\n【頻出】染色堅牢度の定義（変退色への耐性・1〜5級の評価）と評価される条件（光・洗濯・摩擦・汗）はテキスタイル色彩の実務知識として頻出。\n【混同注意】耐光堅牢度（光への耐性）・洗濯堅牢度（洗濯への耐性）・摩擦堅牢度（こすれへの耐性）は同じ「染色堅牢度」の異なる評価項目として区別する。"
