"explanation": "60・30・10ルールは主にインテリア・ファッション・グラフィックデザインで使われる配色の経験則で、ベースカラー（主役色）60%・アソートカラー（サブカラー）30%・アクセントカラー（差し色）10%の面積比でコーディネートすることで視覚的に安定したバランスが得やすいとされる。これはベース70・アソート25・アクセント5の面積比と同じ考え方の変形。\n\nB：60・30・10は色数の基準ではなく面積比の経験則。「60色・30色・10色」という色数の基準ではない。\nC：色相・明度・彩度の問題の割合という統計的法則は存在せず、「60・30・10ルール」の意味として誤り。\nD：60・30・10ルールはインテリア・ファッション両方に適用される面積比のコーディネート原則であり、「ファッションのみ・インテリアには適用されない」は誤り。\n\n【頻出】ベースカラー・アソートカラー・アクセントカラーの面積比（70:25:5または60:30:10）はコーディネートの実践原則として頻出。\n【混同注意】「70:25:5」と「60:30:10」は同じ考え方を表す2つの近い比率。どちらの数値で出題されても「大面積:中面積:小面積=ベース:アソート:アクセント」という構造を理解していれば対応できる。"
