"explanation": "色彩の三要素（色相・明度・彩度）は色を体系的に分析・記述・伝達するための基礎概念であり、配色計画（調和の原理）・インテリア設計（空間の広さ感・重量感・温度感）・ファッションコーディネート・照明設計（明度管理）・マーケティング（色のイメージ）など実務のあらゆる場面で活用される。三要素を理解することで色彩の問題を論理的・体系的に分析できる。\n\nA：三要素は理論と実務の橋渡しをする重要な概念であり、「実務では使用されない」は誤り。\nC：色相・明度・彩度の三要素はそれぞれ独立した重要な属性であり、「色相のみが最重要」という一面的な見方は誤り。問題の目的によって重視すべき属性が変わる。\nD：三要素は数値表現と感覚的判断の両方に対応できる柔軟な概念。「数値のみで感覚とは相容れない」は誤り。カラーコーディネートは数値管理と感覚的判断の両方を活用する。\n\n【頻出】色彩の三要素の実務応用の広がり（配色・インテリア・ファッション・照明・マーケティング）は検定の総合問題として頻出。\n【混同注意】「理論（色彩学）」と「実務（デザイン・コーディネート）」を対立するものとして見る誤解が典型的な誤答パターン。色彩学の理論は実務の問題解決ツールとして機能する。"
