"explanation": "色彩計画においてターゲット設定が重要なのは、対象者（年齢層・性別・文化的背景・ライフスタイル・価値観）によって色の好み・イメージ・連想・心理的反応が異なるためである。幼児向け（高彩度・原色）・高齢者向け（高コントラスト・明度差）・高級ブランド向け（深みのある色・無彩色）などターゲットに応じた最適な色彩選択が可能になる。\n\nA：ターゲット設定を法律で義務付ける規定は存在せず、「法律上の義務・行政指導」という記述は誤り。\nC：ターゲット設定は計画の最初（分析・リサーチ）段階で行うものであり、初期段階で不要という記述は誤り。\nD：ターゲット設定は価格決定だけでなく、色彩・デザイン・コピーライティングなどすべてのコミュニケーション要素に直接影響する。「色彩と無関係」は誤り。\n\n【頻出】色彩計画のプロセスにおけるターゲット設定の位置づけ（分析段階・最初に行う）と、ターゲット特性が色彩選択に与える影響は色彩計画の総合問題として頻出。\n【混同注意】ターゲット設定（誰に向けるか）とコンセプト設定（何を伝えるか）は色彩計画の連続するが異なるステップ。前者が後者の基礎情報を提供する関係にある。"
