"answer": 1,
"explanation": "カラーコーディネーター検定スタンダードは、色の基礎（光と色・三属性・表色系）から色彩心理（色のイメージ・感情効果）・配色理論（調和論・配色技法）・照明・ファッション・インテリア・グラフィック・環境・文化など幅広い分野への応用まで、色彩の体系的な知識全体を習得することを目的とした資格試験である。\n\nA：物理・化学的分析のみという記述は誤り。スタンダードは理論・心理・実務応用を総合的に扱う。\nC：ファッション・パーソナルカラーのみに限定されず、インテリア・建築・グラフィック・環境・文化など多分野にわたる総合的な色彩知識を問う。\nD：測色機器の操作技術を問う試験ではなく、色彩の総合的な知識・理解を筆記（またはコンピュータ）試験で評価する。\n\n【頻出】検定の学習範囲・目的の理解は試験対策の出発点として重要。スタンダードが「色彩の基礎から応用まで体系的に学ぶ」という総合的な性格を持つことを確認する。\n【混同注意】カラーコーディネーター検定（東京商工会議所）とカラーコーディネート検定・色彩検定（AFT）は異なる実施機関の資格。試験の性格・出題傾向を混同しないよう注意。"
