"answer": 1,
"explanation": "食卓の配色計画では料理そのものの色彩（赤いトマト・緑のサラダ・白ごはん・茶色の肉など）と食器の色・テーブルクロス・装飾の色が互いに影響し合う。全体として食欲を促す暖色系・鮮度を感じさせる緑・清潔感の白など、日本の五色（赤・白・黄・緑・黒）の考え方も取り入れながら視覚的に美しく食欲を高める配色を意図的に計画することが食卓デザインの重要な要素。\n\nA：食器・テーブルクロス・料理の色は相互に視覚的影響を与え合い、全体の印象・食欲に影響する。「無関係・統一感不要」は誤り。\nC：同系色統一が最善というのは一概に正しくない。補色対比（赤いトマト×緑のバジル）や多色使いが食欲・美しさを高める場合も多い。\nD：食器の色は「盛りつけた料理の色を引き立てる背景」として機能し、料理の色の見え方に影響する（白い食器は料理の色が鮮やかに見える効果など）。「全く影響しない」は誤り。\n\n【頻出】食卓配色における料理と食器・テーブルウェアの色の調和、および日本の五色の概念は食文化と色彩の応用として頻出。\n【混同注意】「色の対比（補色を並べると互いが引き立つ）」という配色理論が食卓でも積極的に活用されることを理解する。対比が「不快」ではなく「食欲増進」の演出に使われる例として覚える。"
