"explanation": "婚礼の配色は文化・宗教・地域・個人によって多様だが、欧米（白：純潔・新しい始まり）・日本（白無垢・色打掛の赤・金）・中国（赤：幸運・繁栄）・インド（赤・金）など多くの文化で祝祭・純潔・幸福・繁栄のイメージを持つ色（白・赤・金・桃色など）が選ばれる傾向がある。現代では個人の好みによる多様な色の婚礼も一般的。\n\nB：婚礼の色を白のみに法律で規定する国際的な規定は存在しない。文化・個人の選択によって多様な色が使われる。\nC：黒の礼装は欧米のタキシード・フォーマルスーツで使われるが、「黒のみが正式で白・色物は禁止」という記述は事実と異なり誤り。\nD：婚礼の配色は気候・季節だけでなく、文化・宗教・家族の伝統・個人の価値観・トレンドなど多様な要因が影響する。「気候・季節のみ」は誤り。\n\n【頻出】婚礼・ハレの場の色彩（文化による違い・白・赤・金・桃色などの祝祭色）は色彩文化の比較問題として頻出。\n【混同注意】欧米の白いウエディングドレス（純潔・新たな始まり）と日本の白無垢（清浄・神聖）は異なる文化的背景を持つ「白」の使われ方であることを理解する。"
