"explanation": "美容室・ヘアサロンでは顧客の髪の色・肌の色・カラーリング後の仕上がりを正確に確認する必要があるため、演色性の高い照明（Ra90以上、可能であれば Ra95以上）が施術スペースに推奨される。また店舗の雰囲気づくりにも色温度の選択（ラグジュアリーなら低色温度、清潔・明るいなら高色温度）が重要な役割を果たす。\n\nB：演色性が低い照明では顧客の髪・肌の色が不正確に見え、施術後の仕上がりが実際の自然光下と異なる印象を与える問題が生じる。「照度のみで十分」は誤り。\nC：低演色性照明では色の正確な確認ができず、カラーリングの仕上がり確認が困難。「低演色性が最適」は誤り。\nD：照明を暗くすると施術の安全性・正確性が低下する。「完全に暗くすることが推奨」は誤り。\n\n【頻出】美容室・アパレル試着室など色の正確な確認が重要な空間への高演色性照明の必要性は実務知識として頻出。\n【混同注意】演色性（色の正確な再現性・Ra値）と色温度（光の暖冷感・K値）は独立した指標。美容室では両方を適切に選択する必要があるが、最優先は演色性の確保。"
